local M = class("SimulateOutComeModel", LikeOO.OODataBase)

function M:onCreate()
    M.super.onCreate(self)
    self:refreshData()
    self.m_selectIndex = 1
    self:getData("book_index",{open_id = self.m_openId, version = self.m_version})
end

function M:setSelectIndex(index)
    self.m_selectIndex = index
end

function M:refreshData()
    self.m_openId = self.m_params.open_id
    self.m_version = self.m_params.version
end

function M:onEnter()
    local endXlsxData = ConfigManager:getCfgByName("reopen_result")
    local firstCount = 0
    local lastCount = 0
    for _, itemData in pairs(endXlsxData) do
        if itemData.type == 1 then
            firstCount = firstCount + 1
        elseif itemData.type == 2 then
            lastCount = lastCount + 1
        end
    end
    self.endListData = {}
    local endings = self.m_data.endings
    local endCount =  table.nums(endings)
    for index = 1, endCount do
        local itemEndData = endings[index]
        local firstEndValue = itemEndData[1]
        local lastEndValue = itemEndData[2]
        if firstEndValue and lastEndValue then
            local firstValue = ""
            if firstEndValue > 0 then
                local firstItemData = endXlsxData[firstEndValue]
                firstValue = Language:getTextByKey(firstItemData.des)
            end
            local lastItemData = endXlsxData[lastEndValue]
            local endingValue = firstValue.. Language:getTextByKey(lastItemData.des)
            table.insert(self.endListData, {
                value = endingValue,
                isEmpty = false,
            })
        end
    end
    local result_allXlsxData = ConfigManager:getCfgByName("reopen_result_all")
    self.allEndCount = table.nums(result_allXlsxData)
    self.curEndCount = endCount
    if self.curEndCount < self.allEndCount then
        for index = (endCount + 1), self.allEndCount do
            table.insert(self.endListData, {
                value = "?????",
                isEmpty = true,
            })
        end
    end
    
    self.eventListData = {}
    local egg_events = self.m_data.egg_events
    local eggEventCount =  table.nums(egg_events)
    local eventsXlsxData = ConfigManager:getCfgByName("reopen_events")
    for index = 1, eggEventCount do
        local eventIndex = tonumber(egg_events[index])
        local itemValue = eventsXlsxData[eventIndex]
        table.insert(self.eventListData, {
            value = Language:getTextByKey(itemValue.title_special),
            isEmpty = false,
        })
    end
    self.allEggEventCount = 0
    self.curEggEventCount = eggEventCount
    for _, itemData in pairs(eventsXlsxData) do
        if (itemData.type2 == 0) and (itemData.type == 3) then
            self.allEggEventCount = self.allEggEventCount + 1
        end
    end
    if eggEventCount < self.allEggEventCount then
        for index = (eggEventCount + 1), self.allEggEventCount do
            table.insert(self.eventListData, {
                value = "?????",
                isEmpty = true,
            })
        end
    end
end

return M